mapper.select:
select *
from pilipili.user_action
where video_id = #{videoId}
and user_id = #{userId}
and action_type = #{actionType}

    and comment_id = #{commentId}

select *
from pilipili.user_action
where video_id = #{videoId} and user_id = #{userId}

    and action_type in(

        #{type}
    )

select *

    , v.video_cover, v.video_name

from pilipili.user_action u

    right join pilipili.video_info v on u.video_id = v.video_id

where u.user_id = #{userId} and action_type in(

    #{actionType}
)
order by ${orderByField}

select action_id, user_id, video_id, action_type, DATE_FORMAT(action_time, '%Y-%m-%d')
from pilipili.user_action
where user_id = #{userId}
